import copy
import re
from collections.abc import Mapping

_MEMBER = re.compile(r"[A-Za-z0-9_-]+\Z")


def make_blob_name(member_id, epoch, original_name, max_length=80):
    if not isinstance(member_id, str) or not member_id or not _MEMBER.fullmatch(member_id):
        raise ValueError("invalid member_id")
    if isinstance(epoch, bool) or not isinstance(epoch, int) or epoch < 0:
        raise ValueError("invalid epoch")
    if not isinstance(original_name, str) or not original_name or any(c in original_name for c in ("/", "\\", "\0")):
        raise ValueError("invalid original_name")
    if isinstance(max_length, bool) or not isinstance(max_length, int) or max_length < 1:
        raise ValueError("invalid max_length")
    dot = original_name.find(".")
    extension = original_name[dot + 1:].lower() if 0 < dot < len(original_name) - 1 else ""
    suffix = "_" + str(epoch) + (("." + extension) if extension else "")
    available = max_length - len(suffix)
    if available < 1:
        raise ValueError("max_length is too small")
    return member_id[:available] + suffix


def migrate_schema(schema):
    if not isinstance(schema, Mapping) or not isinstance(schema.get("fields"), Mapping) or "blob" not in schema["fields"]:
        raise ValueError("malformed schema")
    result = copy.deepcopy(schema)
    result["fields"]["blob"] = {
        "kind": "upload",
        "optional": True,
        "max_length": 80,
        "namer": make_blob_name,
    }
    return result

